def cat_file_from_ref(context: ApplicationContext, ref: str, filename: str) -> str:
    """Read file contents using git cat-file"""
    status, out, _ = context.git.cat_file(
        'blob', f'{ref}:{filename}', _raw=True, _readonly=True
    )
    return out


