def complete_merge(self, target_branch):
    source = self._merge_source
    self.exit_merge_mode()
    if not source or not target_branch:
        return
    title = N_('Checkout and Merge')
    text = N_('Checkout "%(target)s" and merge "%(source)s" into it?') % {
        'target': target_branch,
        'source': source,
    }
    if not Interaction.confirm(title, text, '', N_('Checkout && Merge')):
        return
    result = cmds.do(cmds.CheckoutBranch, self.context, target_branch)
    if not result or result[0] != 0:
        return
    merge_result = cmds.do(cmds.MergeBranch, self.context, source)
    self.merge_finished.emit()
    if merge_result and merge_result[0] == 0:
        switch_title = N_('Switch Back')
        switch_text = N_('Switch back to "%s"?') % source
        if Interaction.confirm(
            switch_title, switch_text, '', N_('Switch'), default=False
        ):
            cmds.do(cmds.CheckoutBranch, self.context, source)
            self.merge_finished.emit()

def mouseMoveEvent(self, event):
    if self.is_panning:
        self.pan(event)
        return
    pos = self.mapToScene(event.pos())
    self.last_mouse[0] = pos.x()
    self.last_mouse[1] = pos.y()
    self.handle_event(QtWidgets.QGraphicsView.mouseMoveEvent, event, update=False)

def mouseReleaseEvent(self, event):
